# Code Generated by Sidekick is for learning and experimentation purposes only.
# filename: RECON-01-Health.ps1

$url = "http://localhost:8009/health"

Write-Host "`n► GET $url" -ForegroundColor Yellow
try {
    $r = Invoke-RestMethod -Uri $url -Method GET
    Write-Host "✓ Service healthy" -ForegroundColor Green
    Write-Host "  Status     : $($r.status)"                        -ForegroundColor White
    Write-Host "  Timestamp  : $($r.timestamp)"                     -ForegroundColor White
    Write-Host "`n  ── Scheduler ──────────────────────────────────" -ForegroundColor Cyan
    Write-Host "  Enabled    : $($r.scheduler.enabled)"             -ForegroundColor White
    Write-Host "  Next Run   : $($r.scheduler.next_run)"            -ForegroundColor White
    Write-Host "  Last Run   : $($r.scheduler.last_run)"            -ForegroundColor White
    Write-Host "  Last Run ID: $($r.scheduler.last_run_id)"         -ForegroundColor White
    Write-Host "  Scheduled Runs: $($r.scheduler.total_scheduled_runs)" -ForegroundColor White
    $r | ConvertTo-Json -Depth 4
} catch {
    Write-Host "✗ Failed: $_" -ForegroundColor Red
}
